import {stats,sum,daily,accounts,TODAY} from './data.js';
const paths={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 trades:'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18M7 15h2m4 0h2m-8 3h2"/>',chart:'<path d="M4 3v17h17M7 15l4-5 4 3 6-8"/>',wallet:'<path d="M19 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9H6a3 3 0 0 1-3-3M21 13h-5v4h5"/>',book:'<path d="M5 3h14v18H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Zm0 14h14M7 7h8m-8 4h5"/>',brain:'<path d="M12 5c-1-4-7-2-6 2-4 0-4 6-1 7-2 4 3 7 7 4m0-13c1-4 7-2 6 2 4 0 4 6 1 7 2 4-3 7-7 4V5Zm-4 5 4 2m4-2-4 2m-4 4 4-1m4 1-4-1"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',plug:'<path d="m8 3 2 4m6-4-2 4m-7 0h10v4a5 5 0 0 1-10 0V7Zm5 9v5"/>',settings:'<path d="m9 3-1 3-3 1-2 4 2 2v3l3 2 1 3h6l1-3 3-1 2-4-2-2V8l-3-2-1-3H9Z"/><circle cx="12" cy="12" r="3"/>',chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bell:'<path d="M5 9a7 7 0 0 1 14 0c0 7 2 7 2 9H3c0-2 2-2 2-9m4 12h6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 15v6h16v-6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',upRight:'<path d="M6 18 18 6H7m11 0v11"/>',trend:'<path d="m3 17 6-7 5 4 7-9m-6 0h6v6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8L3 5Z"/>',checkCircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5m-4 8a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',edit:'<path d="m15 4 5 5M4 20l1-6L16 3a2 2 0 0 1 3 0l2 2a2 2 0 0 1 0 3L10 19l-6 1Z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',bot:'<rect x="4" y="7" width="16" height="13" rx="4"/><path d="M12 7V3m-2 0h4M8 12h1m6 0h1m-7 4h6M1 11v5m22-5v5"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',cloud:'<path d="M6 18a5 5 0 0 1 0-10 7 7 0 0 1 13 1 4.5 4.5 0 0 1-1 9H6Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',flag:'<path d="M5 21V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0"/>',trash:'<path d="M3 6h18M9 6V3h6v3m-10 0 1 15h12l1-15M10 10v7m4-7v7"/>',logout:'<path d="M9 4H4v16h5m5-4 5-4-5-4m-6 4h11"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6Zm-9 11 9 5 9-5m-18 5 9 5 9-5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5m0 3v1"/>',checklist:'<path d="m3 6 1 1 2-2m3 1h12M3 12l1 1 2-2m3 1h12M3 18l1 1 2-2m3 1h12"/>',fire:'<path d="M13 3c1 6-6 7-3 12 2-1 3-2 4-5 7 5 5 12-2 12C2 22 2 12 7 8c-1 4 0 5 1 6-1-5 5-5 5-11Z"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',file:'<path d="M14 3H5v18h14V8l-5-5Zm0 0v5h5M8 12h8m-8 4h8"/>',heart:'<path d="M12 21 3 12C-2 5 7-1 12 6c5-7 14-1 9 6l-9 9Z"/>'};
export const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const money=(n,signed=false,dec=2)=>`${n<0?'−':signed&&n>0?'+':''}$${Math.abs(n).toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec})}`;
export const compact=n=>Math.abs(n)>=1000?`${n<0?'−':''}$${(Math.abs(n)/1000).toFixed(1)}k`:money(n,false,0);
export const pct=(n,d=1)=>`${Number(n).toFixed(d)}%`;
export const num=(n,d=2)=>Number.isFinite(n)?n.toFixed(d):'∞';
export const dateLabel=(date,opt={month:'short',day:'numeric'})=>new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{...opt,timeZone:'UTC'});
export const signClass=n=>n>=0?'positive':'negative';
export function sparkline(values,color='#7b9b63',width=75,height=27){if(!values.length)return '';const lo=Math.min(0,...values),hi=Math.max(1,...values),points=values.map((v,i)=>`${i/(values.length-1||1)*(width-2)+1},${height-2-(v-lo)/(hi-lo)*(height-4)}`).join(' ');return `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" aria-hidden="true"><polyline points="${points}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
let chartID=0;
export function equityChart(rows,{balance=0,drawdown=false,small=false,compactLabels=false}={}){
 const ds=daily(rows);let total=balance,peak=balance;const points=[{date:ds[0]?.date||TODAY,value:balance,pnl:0},...ds.map(d=>{total+=d.pnl;peak=Math.max(peak,total);return{date:d.date,value:drawdown?total-peak:total,pnl:d.pnl}})];if(drawdown)points[0].value=0;
 const w=720,h=small?205:245,pad={top:15,right:60,bottom:30,left:10},cw=w-pad.left-pad.right,ch=h-pad.top-pad.bottom;const vals=points.map(p=>p.value),lo=Math.min(...vals),hi=Math.max(...vals),range=Math.max(100,hi-lo),min=drawdown?lo-range*.08:lo-range*.12,max=hi+range*.15;
 const xy=points.map((p,i)=>({x:pad.left+i/(points.length-1||1)*cw,y:pad.top+(max-p.value)/(max-min)*ch,...p}));const line=xy.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+','+p.y.toFixed(1)).join(' ');const area=`${line} L${xy.at(-1).x},${h-pad.bottom} L${pad.left},${h-pad.bottom} Z`;const uid='gradient-'+chartID++;const color=drawdown?'#b87864':'#54855e';
 return `<div class="equity-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${drawdown?'Drawdown':'Equity'} chart across ${ds.length} trading days. Ending at ${money(xy.at(-1).value)}"><defs><linearGradient id="${uid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${drawdown?'#d4ac9f':'#a4c483'}" stop-opacity=".28"/><stop offset="100%" stop-color="${drawdown?'#d4ac9f':'#a4c483'}" stop-opacity=".01"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const y=pad.top+i*ch/4,value=max-(max-min)*i/4;return `<line x1="${pad.left}" x2="${w-pad.right}" y1="${y}" y2="${y}" class="chart-grid"/><text x="${w-pad.right+12}" y="${y+3}" class="chart-label">${esc(compactLabels?compact(value):Math.abs(value)>=1000?`${(value/1000).toFixed(1)}k`:Math.round(value))}</text>`}).join('')}<path d="${area}" fill="url(#${uid})"/><path d="${line}" fill="none" stroke="${color}" stroke-width="2.1" stroke-linejoin="round" stroke-linecap="round"/><circle cx="${xy.at(-1).x}" cy="${xy.at(-1).y}" r="4" fill="${color}" stroke="white" stroke-width="2"/>${xy.filter((p,i)=>i>0).map(p=>`<rect class="chart-hit" x="${p.x-cw/(points.length-1||1)/2}" y="0" width="${cw/(points.length-1||1)}" height="${h-pad.bottom+5}" data-tip="${esc(dateLabel(p.date,{month:'short',day:'numeric',year:'numeric'})+'|'+(drawdown?'Drawdown: ':'Balance: ')+money(p.value)+'|Day P&L: '+money(p.pnl,true))}"><title>${dateLabel(p.date)}: ${money(p.value)}</title></rect>`).join('')}${[0,.25,.5,.75,1].map(fr=>{const p=xy[Math.round(fr*(xy.length-1))];return `<text x="${p.x}" y="${h-7}" class="chart-label" text-anchor="${fr===0?'start':fr===1?'end':'middle'}">${dateLabel(p.date)}</text>`}).join('')}</svg></div>`;
}
export function metricStrip(rows,balance=40000){const s=stats(rows),cum=[];let v=0,wins=0,count=0;const rates=[];daily(rows).forEach(d=>{cum.push(v+=d.pnl);wins+=d.trades.filter(t=>t.pnl>0).length;count+=d.trades.length;rates.push(wins/count*100)});return `<div class="metric-strip"><div class="metric"><div class="metric-label">Net P&L <span class="info-icon" title="Realized profit after commissions and swap">i</span></div><div class="metric-value ${signClass(s.pnl)}">${money(s.pnl,s.pnl>0)}</div><div class="metric-foot"><strong>${s.pnl>=0?'↗':'↘'} ${pct(s.pnl/balance*100)}</strong><span>return on starting balance</span></div><div class="metric-spark">${sparkline(cum)}</div></div><div class="metric"><div class="metric-label">Win rate <span class="info-icon" title="Winning trades divided by all closed trades">i</span></div><div class="metric-value">${num(s.winRate)}<small>%</small></div><div class="metric-foot"><strong>${s.wins} wins</strong><span>of ${s.total} trades</span></div><div class="metric-spark">${sparkline(rates,'#a5b88a')}</div></div><div class="metric"><div class="metric-label">Profit factor <span class="info-icon" title="Sum of winning trade net P&L divided by the absolute sum of losing trade net P&L">i</span></div><div class="metric-value">${num(s.pf)}<small>PF</small></div><div class="metric-foot"><span>${money(sum(rows.filter(t=>t.pnl>0)),false,0)} won / ${money(-sum(rows.filter(t=>t.pnl<0)),false,0)} lost</span></div></div><div class="metric"><div class="metric-label">Expectancy <span class="info-icon" title="Average net P&L per trade">i</span></div><div class="metric-value">${money(s.expectancy)}<small>/trade</small></div><div class="metric-foot"><strong>${num(s.avgR)}R</strong><span>average realized return</span></div></div></div>`;}
export function symbolIcon(symbol){return `<span class="symbol-icon ${symbol==='BTCUSD'?'crypto':symbol==='XAUUSD'?'':'fx'}">${symbol==='XAUUSD'?'Au':symbol==='BTCUSD'?'₿':symbol.slice(0,1)}</span>`;}
export function tradeTable(rows,{full=false,playbooks=[],timezone='Asia/Karachi'}={}){if(!rows.length)return empty('No trades in this view','Try another account, period, or filter.','trades');return `<div class="table-wrap"><table><thead><tr><th>Instrument</th><th>Date & time</th><th>Direction</th>${full?'<th>Account / source</th><th>Setup</th>':''}<th>Net P&L</th><th>Return</th><th>Review</th><th></th></tr></thead><tbody>${rows.map(t=>{const a=accounts.find(a=>a.id===t.account);const localTime=new Date(`${t.date}T${t.time}:00Z`).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:timezone});return `<tr data-trade="${esc(t.id)}" tabindex="0" role="button" aria-label="Review ${esc(t.symbol)} trade ${money(t.pnl,true)}"><td><div class="symbol-cell">${symbolIcon(t.symbol)}<div><span class="symbol-name">${esc(t.symbol)}</span><span class="subtext">${esc(t.session)} session</span></div></div></td><td>${dateLabel(t.date)}<span class="subtext">${localTime} · ${timezone==='Asia/Karachi'?'PKT':timezone==='Europe/London'?'London':timezone==='America/New_York'?'New York':'UTC'}</span></td><td><span class="side-tag ${t.side==='Short'?'short':''}">${icon(t.side==='Long'?'upRight':'arrow',11)} ${t.side}</span></td>${full?`<td>${esc(a?.short||t.account)}<span class="subtext">${t.source==='Bot'?'⚙ Automated':'Discretionary'}</span></td><td>${esc(playbooks.find(p=>p.id===t.strategy)?.name||'Custom setup')}</td>`:''}<td class="money table-money ${signClass(t.pnl)}">${money(t.pnl,true)}</td><td class="numeric ${signClass(t.r)}">${t.r>0?'+':''}${num(t.r)}R</td><td>${t.reviewed?`<span class="status-check">${icon('checkCircle',12)} Reviewed</span>`:'<span class="status-pending">● To review</span>'}</td><td>${icon('chevron',13)}</td></tr>`}).join('')}</tbody></table></div>`;}
export const empty=(title,desc,ico='chart',button='')=>`<div class="empty">${icon(ico,29)}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${button}</div>`;
export function donut(rows){const s=stats(rows),circ=2*Math.PI*48,ratio=s.total?s.wins/s.total:0;return `<div class="performance-top"><div class="donut-wrap"><svg viewBox="0 0 116 116" aria-label="${pct(s.winRate)} winning trades" role="img"><circle cx="58" cy="58" r="48" fill="none" stroke="#e9ddd7" stroke-width="9"/><circle cx="58" cy="58" r="48" fill="none" stroke="#799c60" stroke-width="9" stroke-dasharray="${circ*ratio} ${circ}" stroke-linecap="round"/></svg><div class="donut-center"><strong>${num(s.winRate,1)}<span style="font-size:12px">%</span></strong><small>Win rate</small></div></div><div class="donut-details"><div><div class="flex gap8"><span class="dot"></span><small>Winning trades</small></div><strong>${s.wins}</strong></div><div><div class="flex gap8"><span class="dot loss"></span><small>Losing trades</small></div><strong>${s.losses}</strong></div></div></div><div class="performance-ratio"><div class="between"><span>Avg. win</span><span>Avg. loss</span></div><div class="ratio-bar"><div style="width:${s.avgWin/(s.avgWin-s.avgLoss||1)*100}%"></div></div><div class="between"><strong>${money(s.avgWin)}</strong><span>${money(s.avgLoss)}</span></div></div>`;}
export function sessionBars(rows){const groups=['Asia','London','New York'].map(name=>({name,rows:rows.filter(t=>t.session===name)})),max=Math.max(1,...groups.map(g=>Math.abs(sum(g.rows))));return groups.map((g,i)=>`<div class="session-row"><div class="session-top"><span class="session-name">${icon(['moon','sun','globe'][i],14)} ${g.name} <span class="muted tiny">${['00–08','08–13','13–22'][i]} UTC</span></span><strong class="money ${signClass(sum(g.rows))}" style="font-weight:550">${money(sum(g.rows),true,0)}</strong></div><div class="session-track"><div class="session-fill" style="width:${Math.max(0,Math.abs(sum(g.rows))/max*100)}%;background:${sum(g.rows)<0?'#d3b4a5':i===1?'#577b48':'#b2c696'}"></div></div><div class="session-meta"><span>${g.rows.length} trades</span><span>${pct(stats(g.rows).winRate,0)} win rate</span></div></div>`).join('');}
export function weekdayBars(rows){const vals=[1,2,3,4,5].map(day=>sum(rows.filter(t=>new Date(t.date+'T12:00:00Z').getUTCDay()===day))),max=Math.max(1,...vals.map(Math.abs));return `<div class="weekday-chart">${vals.map((v,i)=>`<div class="weekday-col"><strong class="${signClass(v)}">${compact(v)}</strong><div class="weekday-bar ${v===Math.max(...vals)?'best':''} ${v<0?'loss':''}" style="height:${Math.max(3,Math.abs(v)/max*100)}%" data-tip="${['Monday','Tuesday','Wednesday','Thursday','Friday'][i]}|${money(v,true)}"></div><small>${['Mon','Tue','Wed','Thu','Fri'][i]}</small></div>`).join('')}</div>`;}
export function distribution(rows){const ranges=[[-Infinity,-1],[-1,-.5],[-.5,0],[0,1],[1,2],[2,3],[3,Infinity]],counts=ranges.map(([a,b])=>rows.filter(t=>t.r>=a&&t.r<b).length),max=Math.max(1,...counts);return `<div class="distribution">${counts.map((v,i)=>`<div class="dist-bin"><small>${v}</small><div class="${i<3?'loss':''}" style="height:${v/max*100}%"></div><span>${['< −1R','−1R','−0.5R','0–1R','1–2R','2–3R','3R+'][i]}</span></div>`).join('')}</div>`;}
export const input=(label,name,value,type='text',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" type="${type}" ${extra}></div>`;
export const selectField=(label,name,options,value,extra='')=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${extra}>${options.map(o=>{const v=typeof o==='string'?o:o[0],label=typeof o==='string'?o:o[1];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`}).join('')}</select></div>`;
